// The Sunken Vault, a level for examples/tremor/main.psh
//
// Brushes are convex solids; the space you walk through is what is left
// between them. Coordinates are in meters. A texture tiles at 40 texels per
// meter by default, so a 256-texel texture repeats every 6.4 m. Rooms are
// sized in multiples of 1.6 m. A texture is loaded the first time its name is
// used below; nothing needs declaring up front.
//
//   spawn x= y= z= yaw=<degrees>
//   light x= y= z= radius= brightness=
//   moonlight brightness=
//   box   x0= y0= z0= x1= y1= z1= [keys]
//   ramp  x0= y0= z0= x1= y1= z1= dir=<px|nx|pz|nz> [keys]
//   prism cx= cz= radius= y0= y1= sides= rot=<degrees> [keys]
//   beam  x0= z0= x1= z1= width= y0= y1= [keys]
//   poly  y0= y1= pts=x,z;x,z;... [keys]    (any convex polygon, upright)
//   arch  axis=<x|z> a0= a1= c0= c1= ybase= ytop= segs= [keys]
//   entity type=<kind> x= y= z= yaw=<degrees>
//   door  x0= y0= z0= x1= y1= z1= lift= tex=
//
// An entity stands with its base at x, y, z. The kinds are listed in
// spawn_entity() in entities.psh.
//
// A door fills its box when shut and slides up by `lift` to open when the
// player comes close. Its texture is shown once across each of its two large
// faces. Doors are not in the light bake, so the space a door rises into
// should be solid, and it should sit a little inside its doorway's walls.
//
// Keys: tex= side= top= bottom= nx= px= ny= py= nz= pz= name the texture to
// place on a face, light=<0..15> to force a light level instead of baking one,
// scale=<f> sets the texture density in texels per meter (default 40, so
// scale=20 makes a texture repeat over twice the span),
// alpha=<0..1> makes the brush see-through, blended over whatever stands
// behind it, and lets light through it as well (1, opaque, is the default),
// fit to stretch a texture once across each face, flow to make it swim and
// burn at full brightness whatever is around it,
// turn to give the texture a quarter turn on the face.
//
// Nothing here is lit by hand except the fixtures themselves: every other
// surface takes its light from the lamps below, so the rooms go dark wherever
// the lamps do not reach. `moonlight` is the exception: it comes from the moon
// drawn in the sky, and lights whatever has a clear line to it.

spawn x=-6.4 y=4.8 z=-110 yaw=0

// ===========================================================================
// The canyon: a cleft in the rock running south to the castle, open to the
// sky. It starts on a ledge at y 3.2, drops down a ramp, widens to the east
// and opens out into the forecourt in front of the moat.
//
// The moon hangs a little right of straight ahead, over the castle, and is
// most of the light out here. The castle stands with its back to it, so the
// front of it is lit only by its own lamps and by the moat.
// ===========================================================================

moonlight brightness=0.65

// --- Ground ---

box   x0=-12.8 y0=-6.4 z0=-115.2 x1=0 y1=3.2 z1=-104 tex=rock_craggy top=dirt
ramp  x0=-12.8 y0=0 z0=-104 x1=0 y1=3.2 z1=-91.2 dir=nz tex=rock_craggy top=dirt
box   x0=-12.8 y0=-6.4 z0=-104 x1=0 y1=0 z1=-70.4 tex=dirt
box   x0=-9.6 y0=-6.4 z0=-70.4 x1=6.4 y1=0 z1=-51.2 tex=dirt

