box   x0=2.4 y0=-6.4 z0=-51.2 x1=24 y1=0 z1=-32 tex=dirt
box   x0=-2.4 y0=-6.4 z0=-51.2 x1=2.4 y1=0 z1=-41.6 tex=dirt
box   x0=-2.4 y0=-6.4 z0=-41.6 x1=2.4 y1=0 z1=-32 tex=stone_blocks top=floor_stone scale=20

